import React, { useState, useCallback } from 'react';
import { useDropzone } from 'react-dropzone';
import { XMLParser } from 'fast-xml-parser';
import { Upload, FileText, CheckCircle, AlertCircle, ShieldCheck } from 'lucide-react';
import './App.css';

function App() {
  const [xmlContent, setXmlContent] = useState('');
  const [parsedResult, setParsedResult] = useState(null);
  const [error, setError] = useState(null);

  // 1. Configuration: removeNsp (namespaces) makes traversing standard ISO files much easier
  const parser = new XMLParser({
    ignoreAttributes: false,
    attributeNamePrefix: "@_",
    removeNsp: true 
  });

  const processXML = (xmlString) => {
    try {
      setError(null);
      setParsedResult(null);

      // Parse the XML
      const jsonObj = parser.parse(xmlString);
      const doc = jsonObj.Document || jsonObj; // Handle cases with/without 'Document' root if fragments are pasted

      let type = 'Unknown';
      let isValid = false;
      let extractedData = [];
      let validationMessage = '';

      // --- LOGIC FOR pacs.008.001.08 (SCT Inst Instruction) ---
      // Check specifically for the namespace OR the root tag "FIToFICustomerCreditTransfer"
      if (xmlString.includes('pacs.008.001.08') || doc.FIToFICustomerCreditTransfer) {
        type = 'pacs.008.001.08 (SCT Inst)';

        // Traverse to Header
        const dataRoot = doc.FIToFICustomerCreditTransfer;

        if (dataRoot && dataRoot.GrpHdr) {
            isValid = true;
            validationMessage = "Valid Structure: FIToFICustomerCreditTransfer detected.";

            const txInfo = dataRoot.CdtTrfTxInf;
            // Handle single transaction or array of transactions
            const txCount = Array.isArray(txInfo) ? txInfo.length : (txInfo ? 1 : 0);
            const firstTx = Array.isArray(txInfo) ? txInfo[0] : txInfo;

            extractedData = [
                { label: 'Message ID', value: dataRoot.GrpHdr.MsgId },
                { label: 'Creation Date', value: dataRoot.GrpHdr.CreDtTm },
                { label: 'Nb of Txs', value: dataRoot.GrpHdr.NbOfTxs },
                { label: 'Settlement Method', value: dataRoot.GrpHdr.SttlmInf?.SttlmMtd || 'N/A' },
                { label: 'Instructing Agent', value: dataRoot.GrpHdr.InstgAgt?.FinInstnId?.BICFI || 'N/A' },
                { label: 'Instructed Agent', value: dataRoot.GrpHdr.InstdAgt?.FinInstnId?.BICFI || 'N/A' },
                { label: 'First End-to-End ID', value: firstTx?.PmtId?.EndToEndId || 'N/A' },
                { label: 'First Tx Amount', value: firstTx?.IntrBkSttlmAmt ? `${firstTx.IntrBkSttlmAmt} ${firstTx.IntrBkSttlmAmt['@_Ccy'] || ''}` : 'N/A' }
            ];
        } else {
            validationMessage = "Invalid pacs.008: Missing Group Header (GrpHdr)";
        }
      } 

      // --- LOGIC FOR pacs.002.001.10 (Status Report) ---
      // Check specifically for namespace OR root tag "FIToFIPaymentStatusReport"
      else if (xmlString.includes('pacs.002.001.10') || doc.FIToFIPaymentStatusReport) {
        type = 'pacs.002.001.10 (Status Report)';

        const dataRoot = doc.FIToFIPaymentStatusReport;

        if (dataRoot && dataRoot.GrpHdr) {
            isValid = true;
            validationMessage = "Valid Structure: FIToFIPaymentStatusReport detected.";

            const txInfo = dataRoot.TxInfAndSts;
            const firstTx = Array.isArray(txInfo) ? txInfo[0] : txInfo;

            extractedData = [
                { label: 'Message ID', value: dataRoot.GrpHdr.MsgId },
                { label: 'Creation Date', value: dataRoot.GrpHdr.CreDtTm },
                { label: 'Original Msg ID', value: dataRoot.OriginalGroupInformationAndStatus?.OrgnlMsgId || 'N/A' },
                { label: 'Group Status', value: dataRoot.OriginalGroupInformationAndStatus?.GrpSts || 'Mixed/Partially' },
                { label: 'Tx Status (First)', value: firstTx?.TxSts || 'N/A' },
                { label: 'Reason Code', value: firstTx?.StsRsnInf?.Rsn?.Cd || 'N/A' }
            ];
        } else {
             validationMessage = "Invalid pacs.002: Missing Group Header";
        }
      } else {
          validationMessage = "Could not identify pacs.008.001.08 or pacs.002.001.10 signatures.";
      }

      setParsedResult({
        type,
        isValid,
        message: validationMessage,
        data: extractedData
      });

    } catch (err) {
      setError("XML Parsing Error. Ensure the file is valid XML.");
      console.error(err);
    }
  };

  const onDrop = useCallback((acceptedFiles) => {
    const file = acceptedFiles[0];
    const reader = new FileReader();
    reader.onload = () => {
      const binaryStr = reader.result;
      setXmlContent(binaryStr);
      processXML(binaryStr);
    };
    reader.readAsText(file);
  }, []);

  const { getRootProps, getInputProps } = useDropzone({ 
    onDrop, 
    accept: {'text/xml': ['.xml'], 'application/xml': ['.xml']} 
  });

  return (
    <div className="container">
      <div className="header">
        <h1>SCT Inst Validator</h1>
        <p>Supports <strong>pacs.008.001.08</strong> & <strong>pacs.002.001.10</strong></p>
      </div>

      <div className="input-methods">
        <div className="card">
            <h3><Upload size={20} style={{marginRight:'8px', verticalAlign:'bottom'}}/> Upload File</h3>
            <div {...getRootProps({ className: 'dropzone' })}>
                <input {...getInputProps()} />
                <p>Drag & drop XML file here</p>
            </div>
        </div>

        <div className="card">
            <h3><FileText size={20} style={{marginRight:'8px', verticalAlign:'bottom'}}/> Paste XML</h3>
            <textarea 
                placeholder="<Document xmlns=...>" 
                value={xmlContent}
                onChange={(e) => setXmlContent(e.target.value)}
            />
            <button className="btn" onClick={() => processXML(xmlContent)}>Validate</button>
        </div>
      </div>

      {error && (
          <div className="card" style={{borderColor: '#dc3545', color: '#dc3545'}}>
              <AlertCircle size={20} style={{verticalAlign: 'bottom'}}/> {error}
          </div>
      )}

      {parsedResult && !error && (
        <div className="results-area card">
            <div style={{display: 'flex', justifyContent: 'space-between', alignItems: 'center'}}>
                <h2>Analysis Results</h2>
                <span className={`badge ${parsedResult.isValid ? 'badge-success' : 'badge-error'}`}>
                    {parsedResult.isValid ? 'VALID' : 'INVALID'}
                </span>
            </div>

            <div style={{marginTop: '15px'}}>
                <strong>Detected: </strong> <span className="badge badge-info">{parsedResult.type}</span>
            </div>

            <p>{parsedResult.message}</p>

            {parsedResult.data.length > 0 && (
                <>
                <h3>Extracted Values</h3>
                <table>
                    <thead>
                        <tr>
                            <th>Field Name</th>
                            <th>Extracted Value</th>
                        </tr>
                    </thead>
                    <tbody>
                        {parsedResult.data.map((row, index) => (
                            <tr key={index}>
                                <td>{row.label}</td>
                                <td><code>{row.value}</code></td>
                            </tr>
                        ))}
                    </tbody>
                </table>
                </>
            )}
        </div>
      )}
    </div>
  );
}

export default App;
